ALTER TABLE evidence ADD COLUMN quote_start INTEGER;
ALTER TABLE evidence ADD COLUMN quote_end INTEGER;
ALTER TABLE evidence ADD COLUMN region TEXT CHECK(region IS NULL OR json_valid(region));
CREATE TABLE bibliography_entries(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), source_id TEXT UNIQUE REFERENCES sources(id), csl TEXT NOT NULL CHECK(json_valid(csl)), revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX bibliography_project ON bibliography_entries(project_id);
CREATE TABLE bibliography_history(id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES bibliography_entries(id), revision INTEGER NOT NULL, csl TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(entry_id,revision));
CREATE TABLE research_questions(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, detail TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE claims(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), question_id TEXT NOT NULL REFERENCES research_questions(id), body TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('claim','alternative','next_step')), status TEXT NOT NULL CHECK(status IN ('draft','reviewed')), revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE claim_evidence(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), claim_id TEXT NOT NULL REFERENCES claims(id), evidence_id TEXT NOT NULL REFERENCES evidence(id), relation TEXT NOT NULL CHECK(relation IN ('supports','challenges','context')), created_at TEXT NOT NULL, UNIQUE(claim_id,evidence_id));
CREATE TABLE source_relations(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), from_source TEXT NOT NULL REFERENCES sources(id), to_source TEXT NOT NULL REFERENCES sources(id), kind TEXT NOT NULL CHECK(kind IN ('quotes','reprint','translation','shared_origin')), certainty TEXT NOT NULL CHECK(certainty IN ('suspected','confirmed')), basis TEXT NOT NULL, created_at TEXT NOT NULL, CHECK(from_source<>to_source), UNIQUE(from_source,to_source,kind));
CREATE TABLE search_logs(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), query TEXT NOT NULL, scope TEXT NOT NULL, searched_at TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('found','no_hits','unavailable','partial')), result_count INTEGER, notes TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE evidence_reviews(evidence_id TEXT NOT NULL REFERENCES evidence(id), version_id TEXT NOT NULL REFERENCES source_versions(id), project_id TEXT NOT NULL REFERENCES projects(id), created_at TEXT NOT NULL, PRIMARY KEY(evidence_id,version_id));
CREATE TABLE research_jobs(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id), project_id TEXT NOT NULL REFERENCES projects(id), model_id TEXT NOT NULL, model_snapshot TEXT NOT NULL CHECK(json_valid(model_snapshot)), version_ids TEXT NOT NULL CHECK(json_valid(version_ids)), prompt TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('queued','running','paused','succeeded','failed','cancelled','uncertain')), stage TEXT NOT NULL DEFAULT 'queued', result TEXT, error TEXT, input_tokens INTEGER NOT NULL DEFAULT 0, output_tokens INTEGER NOT NULL DEFAULT 0, reserved_units INTEGER NOT NULL, input_rate REAL NOT NULL, output_rate REAL NOT NULL, max_output INTEGER NOT NULL, attempt INTEGER NOT NULL DEFAULT 0, dispatched_at TEXT, started_at TEXT, finished_at TEXT, created_at TEXT NOT NULL);
CREATE INDEX jobs_owner ON research_jobs(owner_id,created_at);
CREATE INDEX jobs_dispatch ON research_jobs(status,dispatched_at);
CREATE TABLE project_budgets(project_id TEXT PRIMARY KEY REFERENCES projects(id), limit_units INTEGER NOT NULL CHECK(limit_units>=0), committed_units INTEGER NOT NULL DEFAULT 0 CHECK(committed_units>=0));
CREATE TABLE research_watches(id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES user(id), project_id TEXT NOT NULL REFERENCES projects(id), query TEXT NOT NULL, interval_days INTEGER NOT NULL CHECK(interval_days IN (1,7)), enabled INTEGER NOT NULL DEFAULT 1, next_run TEXT NOT NULL, checked_at TEXT, error TEXT, created_at TEXT NOT NULL);
CREATE TABLE research_inbox(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), item_key TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN ('task','watch')), title TEXT NOT NULL, body TEXT NOT NULL, url TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','dismissed')), created_at TEXT NOT NULL);
CREATE INDEX questions_project ON research_questions(project_id);
CREATE INDEX claims_project ON claims(project_id);
CREATE INDEX claim_evidence_project ON claim_evidence(project_id);
CREATE INDEX source_relations_project ON source_relations(project_id);
CREATE INDEX search_logs_project ON search_logs(project_id);
CREATE INDEX inbox_project ON research_inbox(project_id);
CREATE INDEX watches_due ON research_watches(enabled,next_run);
